import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse(`{"title":"ADR-0002 — SQLite pure-Go con FTS5 trigram per l'indice locale (SPIKE-02)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0002-sqlite-fts5-trigram.md","filePath":"adr/0002-sqlite-fts5-trigram.md"}`),i={name:"adr/0002-sqlite-fts5-trigram.md"};function n(s,e,c,d,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0002-—-sqlite-pure-go-con-fts5-trigram-per-l-indice-locale-spike-02" tabindex="-1">ADR-0002 — SQLite pure-Go con FTS5 <code>trigram</code> per l&#39;indice locale (SPIKE-02) <a class="header-anchor" href="#adr-0002-—-sqlite-pure-go-con-fts5-trigram-per-l-indice-locale-spike-02" aria-label="Permalink to &quot;ADR-0002 — SQLite pure-Go con FTS5 `trigram` per l&#39;indice locale (SPIKE-02)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Data</strong></td><td>2026-10-23</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.4 (ricerca), §2.5 <code>store</code>, Appendice A (ricerca &lt; 200 ms su 50k note)</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>La ricerca deve offrire il matching per sottostringa degli editor di note (≥ 3 caratteri) senza CGO, per compilare il client su tre OS senza toolchain C.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><p><code>modernc.org/sqlite</code> v1.61 (driver <code>database/sql</code> &quot;sqlite&quot;) con <code>CREATE VIRTUAL TABLE fts_content USING fts5(path UNINDEXED, title, body, tokenize = &#39;trigram case_sensitive 0&#39;)</code>. Verificato dal test <code>TestFTS5Trigram</code> (<code>apps/desktop/internal/store</code>): sottostringhe interne, case-insensitive, testo Unicode. Migrazioni con goose su <code>database/sql</code>; <code>journal_mode=WAL</code>, <code>busy_timeout=5000</code>, una sola connessione aperta per database (SQLite serializza le scritture).</p><p>Query sotto i 3 caratteri: nessun risultato dal FTS; in M1-WP4 scansione lineare sui candidati, come da spec.</p><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong><code>mattn/go-sqlite3</code> (CGO)</strong> — scartata: cross-compilazione e firma più onerose.</li><li><strong>Bleve / indice custom in Go</strong> — scartata: più codice da mantenere, meno strumenti di ispezione.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><p>Il benchmark su 50.000 note sintetiche (obiettivo &lt; 200 ms) resta da eseguire in M1-WP4; se il trigram risultasse troppo lento o grande, il fallback è <code>unicode61</code> con prefix-matching e post-filtro.</p>',11)])])}const g=t(i,[["render",n]]);export{m as __pageData,g as default};
